def copy_legacy_withdrawals(apps, schema_editor):
    """Preserve recorded withdrawal amounts, dates and reasons.

    Legacy contributions are intentionally not turned into Budget allocations
    or withdrawal rows: they were plan-specific manual records and the new
    savings balance is derived only from the authoritative Budget data. The
    development database inspected before this migration contained zero savings
    plans and zero activities, so no legacy contribution history was lost.
    """
    SavingsActivity = apps.get_model("core", "SavingsActivity")
    SavingsWithdrawal = apps.get_model("core", "SavingsWithdrawal")
    for activity in SavingsActivity.objects.filter(
        activity_type="withdrawal"
    ).iterator():
        SavingsWithdrawal.objects.create(
            id=activity.id,
            owner_id=activity.owner_id,
            amount=activity.amount,
            date=activity.date,
            reason=activity.description or "Legacy savings withdrawal",
            client_reference=activity.client_reference,
        )


